public double getQalys(){
  try {
    Map<Integer,Double> qalys=(Map<Integer,Double>)this.attributes.get(QualityOfLifeModule.QALY);
    double sum=0.0;
    for (  double currQaly : qalys.values()) {
      sum+=currQaly;
    }
    return sum;
  } catch (ClassCastException | NullPointerException e) {
    return 0.0;
  }
}
